import socket, sys
h, p, m = sys.argv[1], sys.argv[2], sys.argv[3]
if not (p.isdigit() and m.isdigit()):
    print("UNKNOWN NOT_ATTEMPTED"); sys.exit(0)
try:
    socket.getaddrinfo(h, int(p), proto=socket.IPPROTO_TCP)
except Exception:
    print("FAILED NOT_ATTEMPTED"); sys.exit(0)
try:
    socket.create_connection((h, int(p)), timeout=int(m) / 1000).close(); print("RESOLVED REACHABLE")
except Exception:
    print("RESOLVED UNREACHABLE")
